CREATE TABLE IF NOT EXISTS colaboradores (id INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(255) NOT NULL, departamento VARCHAR(255) NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS usuarios (id INT AUTO_INCREMENT PRIMARY KEY, colaborador_id INT NOT NULL UNIQUE, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, rol VARCHAR(20) NOT NULL CHECK (rol IN ('colaborador','rrhh')), FOREIGN KEY (colaborador_id) REFERENCES colaboradores(id));
CREATE TABLE IF NOT EXISTS sesiones (token_hash CHAR(64) PRIMARY KEY, usuario_id INT NOT NULL, vence DATETIME NOT NULL, FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS saldos_vacaciones (colaborador_id INT PRIMARY KEY, dias DECIMAL(6,2) NOT NULL, FOREIGN KEY (colaborador_id) REFERENCES colaboradores(id));
CREATE TABLE IF NOT EXISTS solicitudes (id INT AUTO_INCREMENT PRIMARY KEY, colaborador_id INT, tipo VARCHAR(100), estado VARCHAR(100), fecha DATE, FOREIGN KEY (colaborador_id) REFERENCES colaboradores(id));
CREATE TABLE IF NOT EXISTS incapacidades (id INT AUTO_INCREMENT PRIMARY KEY, colaborador_id INT, inicio DATE, fin DATE, FOREIGN KEY (colaborador_id) REFERENCES colaboradores(id));
CREATE TABLE IF NOT EXISTS movimientos_personal (id INT AUTO_INCREMENT PRIMARY KEY, colaborador_id INT, tipo VARCHAR(100), fecha DATE, FOREIGN KEY (colaborador_id) REFERENCES colaboradores(id));
CREATE TABLE IF NOT EXISTS consultas_chat (id BIGINT AUTO_INCREMENT PRIMARY KEY, usuario_id INT, pregunta TEXT NOT NULL, creado TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (usuario_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS intervenciones (id BIGINT AUTO_INCREMENT PRIMARY KEY, consulta_id BIGINT, agente VARCHAR(100) NOT NULL, evidencias JSON NOT NULL, latencia_ms INT NOT NULL, escalamiento BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY (consulta_id) REFERENCES consultas_chat(id));
CREATE TABLE IF NOT EXISTS reportes_diarios (fecha DATE PRIMARY KEY, datos JSON NOT NULL, resumen TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS documentos (id VARCHAR(255) PRIMARY KEY, nombre TEXT NOT NULL, version VARCHAR(255), vigencia VARCHAR(255), enlace TEXT NOT NULL, modificado DATETIME, aprobado BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS fragmentos (id BIGINT AUTO_INCREMENT PRIMARY KEY, documento_id VARCHAR(255) NOT NULL, seccion VARCHAR(255) NOT NULL, contenido TEXT NOT NULL, embedding JSON NOT NULL, FOREIGN KEY (documento_id) REFERENCES documentos(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS sincronizaciones (id BIGINT AUTO_INCREMENT PRIMARY KEY, fecha TIMESTAMP DEFAULT CURRENT_TIMESTAMP, resultado TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS calendario_pagos (id INT AUTO_INCREMENT PRIMARY KEY, fecha DATE NOT NULL, descripcion TEXT);
CREATE TABLE IF NOT EXISTS evaluaciones (id INT AUTO_INCREMENT PRIMARY KEY, pregunta TEXT NOT NULL, esperado TEXT, restringida BOOLEAN DEFAULT FALSE);
